const D = { energy: .58, scale: 1, speed: 1, density: .5, visc: .4, hue: 30, x: .5, y: .42, style: 'mixing', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Rayleigh-Taylor instability — heavy fluid stacked on top of light -------------------
// The most impatient arrangement in fluid mechanics. Any dimple in the interface lets heavy
// fluid reach down into light, buoyancy pulls it further, and the dimple runs away: spikes of
// heavy fall, bubbles of light rise between them, and the falling tips shear against the fluid
// they push through until Kelvin-Helmholtz curls each one into the iconic MUSHROOM cap.
//
// This is a real incompressible Boussinesq solver — semi-Lagrangian advection of density and
// momentum, a buoyancy source, and an SOR pressure projection to hold div(u) = 0. The
// projection is the expensive part and also the whole reason it looks right: without it there
// is no pressure to push the bubbles up between the spikes.
//
// Left/right wrap. The top and bottom are held as reservoirs — heavy above, light below — so
// the instability is fed forever and cannot mix itself into a flat grey and stop. That is a
// real configuration (Rayleigh-Taylor turbulence), not a convenience.
//
// vs Kelvin-Helmholtz: that is SHEAR across an interface and it makes a train of billow rolls.
// This is buoyancy acting NORMAL to the interface, and it makes mushrooms.
// -----------------------------------------------------------------------------------------
const TAU = 6.283185307;
const BW = 132, BH = Math.max(60, Math.round(BW * height / width));
const NC = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.U = new Float32Array(NC); S.V = new Float32Array(NC); S.RO = new Float32Array(NC);
  S.U2 = new Float32Array(NC); S.V2 = new Float32Array(NC); S.R2 = new Float32Array(NC);
  S.PR = new Float32Array(NC); S.DV = new Float32Array(NC);
  S.init = false;
}
const U = S.U, V = S.V, RO = S.RO, U2 = S.U2, V2 = S.V2, R2 = S.R2, PR = S.PR, DV = S.DV;

const sd = P.seed | 0;
function fr(i) { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); }

const L = BW / BH, h = 1 / BH;
const tt = K.t;
const en = P.energy;
const y0 = 0.18 + Math.min(1, Math.max(0, P.y)) * 0.50;   // where the interface is hung

if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  U.fill(0); V.fill(0); PR.fill(0);
  const nm = 2 + Math.round(P.density * 6);
  for (let j = 0; j < BH; j++) {
    const y = (j + 0.5) / BH;
    for (let i = 0; i < BW; i++) {
      const x = (i + 0.5) / BH;
      // a seeded broadband ripple on the interface — the modes it will amplify
      let d = 0;
      for (let m = 1; m <= nm; m++) d += (0.030 / m) * Math.sin(TAU * m * x / L + fr(m * 13 + 1) * TAU);
      const yi = y0 + d * Math.max(0.4, P.scale);
      RO[j * BW + i] = 1 - 1 / (1 + Math.exp(-(y - yi) * 90));   // heavy(1) above, light(0) below
    }
  }
}

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dtr = K.t - S.lastT; S.lastT = K.t;
dtr = dtr < 0 ? 0 : (dtr > 0.05 ? 0.05 : dtr);
const dt = dtr * (0.25 + P.speed * 0.75);

const grav = 0.10 + en * 0.20;             // effective g * Atwood
const nuv = 0.00002 + P.visc * 0.00035;

function samp(F, bx, by) {
  // x wraps, y clamps
  let X = bx - Math.floor(bx / BW) * BW;
  let Y = by < 0 ? 0 : (by > BH - 1.001 ? BH - 1.001 : by);
  const x0 = X | 0, y0i = Y | 0, fx = X - x0, fy = Y - y0i;
  const x1 = x0 + 1 >= BW ? 0 : x0 + 1, y1 = y0i + 1 < BH ? y0i + 1 : y0i;
  const a = F[y0i * BW + x0], b = F[y0i * BW + x1], c = F[y1 * BW + x0], d = F[y1 * BW + x1];
  const t0 = a + (b - a) * fx, t1 = c + (d - c) * fx;
  return t0 + (t1 - t0) * fy;
}

// ---- 1. advect u, v, rho (semi-Lagrangian, read from the old fields, write to new) ----
const sc = BH;
for (let j = 0; j < BH; j++) {
  const jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const p = jc + i;
    const bx = i - U[p] * dt * sc, by = j - V[p] * dt * sc;
    U2[p] = samp(U, bx, by); V2[p] = samp(V, bx, by); R2[p] = samp(RO, bx, by);
  }
}
U.set(U2); V.set(V2); RO.set(R2);

// ---- 2. buoyancy + a slow large-scale sloshing force on incommensurate rates ----
const shear = 0.30 * Math.sin(tt * 0.071) + 0.17 * Math.sin(tt * 0.157 + 1.3) + 0.09 * Math.sin(tt * 0.263 + 0.4);
const kick = 0.85 + K.swell * 0.2 + A.bass * 0.5;
for (let j = 0; j < BH; j++) {
  const y = (j + 0.5) / BH, jc = j * BW;
  const prof = Math.sin(TAU * y);
  for (let i = 0; i < BW; i++) {
    const p = jc + i;
    V[p] += grav * (RO[p] - 0.5) * dt * kick;      // heavy sinks (+y is down)
    U[p] += shear * prof * dt * 0.5;
  }
}

// ---- 3. project to divergence free (Stam's formulation), warm-started ----
for (let j = 1; j < BH - 1; j++) {
  const jm = (j - 1) * BW, jp = (j + 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1;
    DV[jc + i] = -0.5 * h * (U[jc + ip] - U[jc + im] + V[jp + i] - V[jm + i]);
  }
}
for (let it = 0; it < 18; it++) {
  for (let j = 1; j < BH - 1; j++) {
    const jm = (j - 1) * BW, jp = (j + 1) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1;
      const t = (DV[jc + i] + PR[jc + im] + PR[jc + ip] + PR[jm + i] + PR[jp + i]) * 0.25;
      PR[jc + i] += (t - PR[jc + i]) * 1.7;
    }
  }
  for (let i = 0; i < BW; i++) { PR[i] = PR[BW + i]; PR[(BH - 1) * BW + i] = PR[(BH - 2) * BW + i]; }
}
for (let j = 1; j < BH - 1; j++) {
  const jm = (j - 1) * BW, jp = (j + 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1;
    U[jc + i] -= 0.5 * (PR[jc + ip] - PR[jc + im]) / h;
    V[jc + i] -= 0.5 * (PR[jp + i] - PR[jm + i]) / h;
  }
}
for (let i = 0; i < BW; i++) { V[i] = 0; V[(BH - 1) * BW + i] = 0; }   // no flow through the lids

// ---- 4. viscosity + the reservoirs that keep feeding the instability ----
{
  const kv = Math.min(0.24, nuv * sc * sc * dt);
  const kr = Math.min(0.5, dt * 1.5);
  const shrp = Math.min(0.45, dt * 5.5 * (1.3 - P.visc * 0.8));   // interface compression
  U2.set(U); V2.set(V); R2.set(RO);
  for (let j = 0; j < BH; j++) {
    const y = (j + 0.5) / BH;
    const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
    // 1 at the lids, 0 by 16% in: heavy is resupplied above, light below, the middle is free
    const dEdge = Math.min(y, 1 - y);
    const wE = Math.max(0, 1 - dEdge / 0.16);
    const tgt = y < 0.5 ? 1 : 0;
    for (let i = 0; i < BW; i++) {
      const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1, p = jc + i;
      const lu = U2[jc + im] + U2[jc + ip] + U2[jm + i] + U2[jp + i] - 4 * U2[p];
      const lv = V2[jc + im] + V2[jc + ip] + V2[jm + i] + V2[jp + i] - 4 * V2[p];
      const lr = R2[jc + im] + R2[jc + ip] + R2[jm + i] + R2[jp + i] - 4 * R2[p];
      U[p] = U2[p] + lu * kv;
      V[p] = V2[p] + lv * kv;
      // Semi-Lagrangian advection is heavily diffusive, and left alone it dissolves the two
      // fluids into one homogeneous grey within ~10s — the mushrooms stop reading entirely.
      // The Allen-Cahn double-well term ro*(1-ro)*(2ro-1) pushes each cell back toward pure
      // heavy or pure light, and balanced against the diffusion it holds the interface at a
      // couple of cells. This is the standard phase-field interface compression, not a hack.
      let ro = R2[p] + lr * kv * 0.12 + (tgt - R2[p]) * wE * kr;
      ro += shrp * ro * (1 - ro) * (2 * ro - 1);
      RO[p] = ro < 0 ? 0 : (ro > 1 ? 1 : ro);
    }
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + Math.sin(tt * 0.019) * 9 + sec * 5) % 360 + 360) % 360;
function pal(m, sp2, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(TAU * (m + hr)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2)), 0.5 + 0.5 * Math.cos(TAU * (m + hr + sp2 * 2))];
}
const cLight = pal(0.03, 0.14, 0.0), cHeavy = pal(0.50, 0.16, 0.0);
const gl = 0.88 + A.treble * 0.3;
const wsc = 5.0 + en * 6.0;

for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = i === 0 ? BW - 1 : i - 1, ip = i === BW - 1 ? 0 : i + 1, p = jc + i;
    const d = RO[p] < 0 ? 0 : (RO[p] > 1 ? 1 : RO[p]);
    const gx = (RO[jc + ip] - RO[jc + im]) * 0.5, gy = (RO[jp + i] - RO[jm + i]) * 0.5;
    const edge = Math.min(1, Math.sqrt(gx * gx + gy * gy) * 5.5);
    const wz = ((V[jc + ip] - V[jc + im]) - (U[jp + i] - U[jm + i])) * 0.5 * sc * wsc;
    let r, gg, b;
    if (style === 'vorticity') {
      // abstracted: forget the dye, show the vorticity the falling spikes deposit — every
      // mushroom cap is a pair of counter-rotating rolls and this is the only view that says so
      const s2 = wz < -1 ? -1 : (wz > 1 ? 1 : wz);
      const v = 0.34;
      const pos = s2 > 0 ? s2 : 0, neg = s2 < 0 ? -s2 : 0;
      r = v + pos * 0.60 - neg * 0.20; gg = v - pos * 0.16 - neg * 0.15; b = v - pos * 0.22 + neg * 0.58;
    } else if (style === 'thermal') {
      const m = Math.min(1, (1 - d) * 0.94 + edge * 0.12);
      r = Math.min(1, m * 2.15); gg = Math.min(1, Math.max(0, m * 2.0 - 0.55));
      b = Math.min(1, Math.max(0, m * 3.1 - 2.05) + Math.max(0, 0.40 - m * 1.5));
    } else if (style === 'ink_wash') {
      const gr = (fr(i * 3.7 + j * 9.1) - 0.5) * 0.05;
      const v = 0.84 - d * 0.66 + gr - edge * 0.13;
      r = v * 0.99; gg = v * 0.972; b = v * 0.93;
    } else if (style === 'spectral') {
      const u = 0.06 + d * 0.56 + edge * 0.10;
      const cc = pal(u, 0.32, 0.0);
      const v = 0.24 + edge * 0.26 + (1 - Math.abs(d - 0.5) * 2) * 0.16;
      r = v * (0.30 + cc[0] * 1.25); gg = v * (0.30 + cc[1] * 1.25); b = v * (0.32 + cc[2] * 1.25);
    } else {                                   // mixing (default)
      // two dyed fluids; the interface catches light, so every fold and mushroom rim reads
      const bl = 0.30 + (1 - d) * 0.20;
      r = (cHeavy[0] * d + cLight[0] * (1 - d)) * bl * 1.35 + 0.035;
      gg = (cHeavy[1] * d + cLight[1] * (1 - d)) * bl * 1.30 + 0.040;
      b = (cHeavy[2] * d + cLight[2] * (1 - d)) * bl * 1.28 + 0.055;
      const e2 = edge * gl * 0.30;
      r += e2 * 1.0; gg += e2 * 0.93; b += e2 * 0.76;
    }
    const o = 4 * p;
    px[o] = r < 0 ? 0 : (r > 1 ? 255 : r * 255);
    px[o + 1] = gg < 0 ? 0 : (gg > 1 ? 255 : gg * 255);
    px[o + 2] = b < 0 ? 0 : (b > 1 ? 255 : b * 255);
    px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
